class Base {
public:
    virtual void foo(); // vtable entry
    int a;
};

class Derived : public Base {
public:
    void foo() override; // overrides base virtual
    int b;
};

// Implementation notes:
// - The compiler generates a vtable for each polymorphic class.
// - Each object of such class contains a hidden vptr pointing to the class's vtable.
// - During construction, the vptr is initialized to the appropriate vtable, considering inheritance.
// - Destructors are virtual to ensure proper cleanup in inheritance hierarchies.
// - Compiler may optimize vtable placement and object layout for cache efficiency.
